import React, { useState } from 'react';
import styled from 'styled-components';
import SectionTitle from '../components/SectionTitle';
import ProjectCard from '../components/ProjectCard';
import Button from '../components/Button';

const ProjectsContainer = styled.section`
  padding: 5rem 0;

  @media (max-width: 768px) {
    padding: 3rem 0;
  }
`;

const Subtitle = styled.h3`
  font-size: 1.5rem;
  margin-bottom: 2rem;
  color: ${props => props.theme.fourthColor};

  @media (max-width: 768px) {
    font-size: 1.25rem;
  }
`;

const ProjectsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
  margin-bottom: 3rem;

  @media (max-width: 1024px) {
    grid-template-columns: repeat(2, 1fr);
  }

  @media (max-width: 576px) {
    grid-template-columns: 1fr;
  }
`;

const ButtonContainer = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 2rem;
`;

const TabsContainer = styled.div`
  display: flex;
  gap: 1rem;
  margin-top: 2rem;
  justify-content: center;

  @media (max-width: 576px) {
    flex-direction: column;
    align-items: center;
  }
`;

const TabButton = styled.button`
  padding: 0.75rem 2rem;
  background-color: ${props => props.active ? props.theme.thirdColor : props.theme.secondaryColor};
  color: ${props => props.active ? props.theme.mainColor : props.theme.thirdColor};
  border: 1px solid ${props => props.theme.thirdColor};
  border-radius: 4px;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.3s ease;

  &:hover {
    background-color: ${props => props.active ? props.theme.fourthColor : props.theme.accentColor};
  }
`;

const ProjectsPage = ({ strings }) => {
  const [activeTab, setActiveTab] = useState('figma');
  const [showAllFigma, setShowAllFigma] = useState(false);
  const [showAllAdobe, setShowAllAdobe] = useState(false);
  const [showAll3D, setShowAll3D] = useState(false);

  const figmaProjects = [
    {
      id: 1,
      title: 'UI/UX Design',
      description: 'Mobile app interface for fitness tracking',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_3.png'
    },
    {
      id: 2,
      title: 'Web Design',
      description: 'E-commerce website redesign',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_6.png'
    },
    {
      id: 3,
      title: 'Dashboard Design',
      description: 'Analytics dashboard for SaaS platform',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_4.png'
    },
    {
      id: 4,
      title: 'Mobile App',
      description: 'Delivery service mobile application',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_5.png'
    },
    {
      id: 5,
      title: 'Wireframing',
      description: 'Online education platform wireframes',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_7.png'
    },
    {
      id: 6,
      title: 'Prototype',
      description: 'Interactive banking app prototype',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_1.png'
    }
  ];

  const adobeProjects = [
    {
      id: 7,
      title: 'Logo Design',
      description: 'Corporate identity for a coffee shop',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/adobe_1.png'
    },
    {
      id: 8,
      title: 'Branding',
      description: 'Complete branding for a tech startup',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/adobe_2.png'
    },
    {
      id: 9,
      title: 'Print Design',
      description: 'Magazine layout and typography',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/adobe_3.png'
    },
    {
      id: 10,
      title: 'Illustration',
      description: 'Digital illustrations for a children\'s book',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/adobe_4.png'
    },
    {
      id: 11,
      title: 'Advertisement',
      description: 'Social media marketing campaign',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/adobe_5.png'
    },
    {
      id: 12,
      title: 'Poster Design',
      description: 'Event promotional materials',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/adobe_6.png'
    }
  ];

  const threeDProjects = [
    {
      id: 13,
      title: '3D Modeling',
      description: 'Product visualization for marketing',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/3d_2.png'
    },
    {
      id: 14,
      title: 'Packaging Design',
      description: 'Eco-friendly product packaging',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/3d_3.png'
    },
    {
      id: 15,
      title: 'Interior Visualization',
      description: '3D rendering of living spaces',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/3d_1.png'
    },
    {
      id: 16,
      title: 'Character Design',
      description: '3D character for animation',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/3d_4.png'
    },
    {
      id: 17,
      title: 'Product Design',
      description: '3D modeling for consumer products',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/3d_5.png'
    },
    {
      id: 18,
      title: 'Architectural Visualization',
      description: 'Building exterior visualization',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/3d_6.png'
    }
  ];

  const getDisplayedProjects = () => {
    switch(activeTab) {
      case 'figma':
        return showAllFigma ? figmaProjects : figmaProjects.slice(0, 3);
      case 'adobe':
        return showAllAdobe ? adobeProjects : adobeProjects.slice(0, 3);
      case '3d':
        return showAll3D ? threeDProjects : threeDProjects.slice(0, 3);
      default:
        return [];
    }
  };

  const handleViewToggle = () => {
    switch(activeTab) {
      case 'figma':
        setShowAllFigma(!showAllFigma);
        break;
      case 'adobe':
        setShowAllAdobe(!showAllAdobe);
        break;
      case '3d':
        setShowAll3D(!showAll3D);
        break;
      default:
        break;
    }
  };

  const isShowingAll = () => {
    switch(activeTab) {
      case 'figma':
        return showAllFigma;
      case 'adobe':
        return showAllAdobe;
      case '3d':
        return showAll3D;
      default:
        return false;
    }
  };

  return (
    <ProjectsContainer id="projects">
      <SectionTitle>{strings.projects}</SectionTitle>
      <Subtitle>{strings.myWorks}</Subtitle>

      <TabsContainer>
        <TabButton 
          active={activeTab === 'figma'} 
          onClick={() => setActiveTab('figma')}
        >
          Figma
        </TabButton>
        <TabButton 
          active={activeTab === 'adobe'} 
          onClick={() => setActiveTab('adobe')}
        >
          Adobe
        </TabButton>
        <TabButton 
          active={activeTab === '3d'} 
          onClick={() => setActiveTab('3d')}
        >
          3D
        </TabButton>
      </TabsContainer>

      <ProjectsGrid>
        {getDisplayedProjects().map(project => (
          <ProjectCard key={project.id} project={project} />
        ))}
      </ProjectsGrid>

      <ButtonContainer>
        <Button onClick={handleViewToggle}>
          {isShowingAll() ? strings.hide : strings.view}
        </Button>
      </ButtonContainer>
    </ProjectsContainer>
  );
};

export default ProjectsPage;
